function layout(){
  const pg=document.body.dataset.page;
  const nav=[['index.html','Главная','index'],[FORUM,'Форум','forum',1],['start.html','Начать игру','start'],['shop.html','Магазин','shop'],[HELP,'Помощь','help',1]];
  const links=nav.map(n=>`<a href="${n[0]}"${n[3]?' target="_blank" rel="noopener"':''} class="${pg===n[2]?'on':''}">${n[1]}${n[3]?ICO.ext:''}</a>`).join('');
  const acc=`<div class="acc"><a class="btn btn-ghost btn-sm" href="login.html">Авторизация</a><a class="btn btn-red btn-sm" href="register.html">Регистрация</a></div>`;
  document.body.insertAdjacentHTML('afterbegin',`<header class="hdr" id="hdr"><div class="wrap"><a class="logo" href="index.html"><img src="${B}/img/logo/default.svg" alt="Малиновка"></a><nav class="nav">${links}</nav>${acc}<button class="burger" id="burger" aria-label="Меню"><span></span></button></div></header><nav class="mnav">${links}${acc}</nav>`);
  const main=$('main');
  main.insertAdjacentHTML('afterend',`<section class="demo-end"><div>ДЕМОВЕРСИЯ</div><p>Это концепт нового сайта, не официальный сайт онлайн-игры Малиновка. Тексты, магазин и изображения взяты с malinovka.org и показаны для ознакомления. Вход, регистрация и оплата работают только на официальном сайте.</p></section><footer class="ftr"><div class="wrap"><a class="logo" href="index.html"><img src="${B}/img/logo/default.svg" alt="Малиновка"></a><div class="links"><a href="${DOCS.agr}" target="_blank" rel="noopener">Пользовательское соглашение</a><a href="${DOCS.offer}" target="_blank" rel="noopener">Публичная оферта</a><a href="contacts.html">Контакты</a></div><div class="soc"><a href="https://vk.ru/malinovka" target="_blank" rel="noopener" aria-label="ВКонтакте"><img src="${B}/img/icons/svg/vk_logo.svg" alt=""></a><a href="${HELP}" target="_blank" rel="noopener" aria-label="Помощь"><img src="${B}/img/icons/svg/question.svg" alt=""></a><a href="https://malinovka.live" target="_blank" rel="noopener" aria-label="Статус серверов"><img src="${B}/img/icons/svg/statuspage.svg" alt=""></a><span class="age">18+</span></div><div class="copy">Malinovka Team © 2017-2026</div></div></footer><div class="toast" id="toast"></div>`);
  $('#burger').onclick=()=>document.body.classList.toggle('menu-open');
  $$('.mnav a').forEach(a=>a.addEventListener('click',()=>document.body.classList.remove('menu-open')));
  const h=$('#hdr');const on=()=>h.classList.toggle('solid',scrollY>40);on();addEventListener('scroll',on,{passive:true});
}

let toastT;
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastT);toastT=setTimeout(()=>e.classList.remove('show'),3400)}

function reveal(){
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('show');io.unobserve(e.target)}}),{threshold:.08});
  $$('.rv').forEach(el=>io.observe(el));
}

function modal(html,wide){
  let m=$('#modal');
  if(!m){document.body.insertAdjacentHTML('beforeend','<div class="modal" id="modal"><div class="mbox"><button class="x" aria-label="Закрыть">✕</button><div class="mc"></div></div></div>');m=$('#modal');m.onclick=e=>{if(e.target===m||e.target.closest('.x'))closeModal()}}
  $('.mbox',m).classList.toggle('wide',!!wide);
  $('.mc',m).innerHTML=html;m.classList.add('open');document.body.style.overflow='hidden';return m;
}
function closeModal(){const m=$('#modal');if(m){m.classList.remove('open');document.body.style.overflow=''}}
addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeLb()}});

function pay(title,price,max=1,extra=''){
  let q=1,method=0;
  const m=modal(`<h3>Оплата</h3><p class="sub">${title}${extra?'<br>'+extra:''}</p>
  <div class="qty"><span>Количество</span><div class="ctl"><button data-q="-1">−</button><b id="q">1</b><button data-q="1">+</button></div></div>
  <div class="pays">${PAYS.map((p,i)=>`<button class="pay${i===0?' on':''}" data-i="${i}"><img src="${B}/img/pay/systems/${p[0]}.svg" alt="">${p[1]}</button>`).join('')}</div>
  <p class="hint">Для оплаты могут потребоваться сертификаты Минцифры. Вы можете использовать <a href="https://yandex.ru/project/browser/sert/1" target="_blank" rel="noopener">Яндекс.Браузер</a> или установить их вручную.</p>
  <label class="check"><input type="checkbox" id="agree"><span>Я подтверждаю, что прочитал(а) и принимаю <a href="${DOCS.agr}" target="_blank" rel="noopener">пользовательское соглашение</a> и <a href="${DOCS.offer}" target="_blank" rel="noopener">публичную оферту</a>.</span></label>
  <div class="total"><span>Чек будет отправлен на привязанную электронную почту.</span><b id="tot">${fmt(price)} ₽</b></div>
  <button class="btn btn-red btn-block" id="go">${ICO.cart}Продолжить покупку</button>
  <div class="mlinks"><a href="${DOCS.payinfo}" target="_blank" rel="noopener">Информация о процессе оплаты</a><a href="${DOCS.paysec}" target="_blank" rel="noopener">Политика безопасности платежей</a></div>`);
  const upd=()=>{$('#q',m).textContent=q;$('#tot',m).textContent=fmt(price*q)+' ₽'};
  $$('[data-q]',m).forEach(b=>b.onclick=()=>{q=Math.min(max,Math.max(1,q+ +b.dataset.q));upd()});
  $$('.pay',m).forEach(b=>b.onclick=()=>{$$('.pay',m).forEach(x=>x.classList.remove('on'));b.classList.add('on');method=+b.dataset.i});
  $('#go',m).onclick=()=>{if(!$('#agree',m).checked){toast('Подтвердите согласие с соглашением и офертой');return}toast('Демоверсия: оплата проходит на официальном сайте malinovka.org')};
}

