let lbList=[],lbI=0;
function lb(list,i){
  let l=$('#lb');
  if(!l){document.body.insertAdjacentHTML('beforeend','<div class="lb" id="lb"><img alt=""><button class="x" aria-label="Закрыть">✕</button></div>');l=$('#lb');l.onclick=e=>{if(e.target.tagName!=='IMG')closeLb();else{lbI=(lbI+1)%lbList.length;$('img',l).src=lbList[lbI]}}}
  lbList=list;lbI=i||0;$('img',l).src=list[lbI];l.classList.add('open');
}
