function online(){
  const el=$('#onl');if(!el)return;
  try{
    const ws=new WebSocket('wss://ws.malinovka.org/fd0f4401e0ebff87a3dc5dc70ebcfd8e/web');
    ws.onopen=()=>ws.send(JSON.stringify({type:'auth',data:{type:'web',webSession:''}}));
    ws.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.type==='update_online'){const n=parseInt(d.data.players);if(n)el.textContent=fmt(n)}}catch(_){}};
  }catch(_){}
}

const img=c=>{const t=c[0],id=c.slice(1);if(t==='c')return [B+'/img/product/cars/290/'+id+'.png',B+'/img/product/cars/725/'+id+'.png'];if(t==='s')return [ST+'/img/skins/350/'+id+'.png',ST+'/img/skins/840/'+id+'.png'];return [ST+'/img/backskins/350/'+id+'.png',ST+'/img/backskins/840/'+id+'.png']};

function itemCard(r,color){
  const [name,ex,pics,groups]=r;
  const ps=pics.split(' ').map(img);
  const base=groups.find(g=>g[0]===-1)||[-1];
  const kv=base.slice(1).map(i=>DATA.D[i]).map(s=>{const [k,v]=s.split('|');return `<div class="${(v||'').length>34?'w':''}"><span>${k}</span><b>${v||''}</b></div>`}).join('');
  const rest=groups.filter(g=>g[0]!==-1).map(g=>`<h5>${DATA.D[g[0]]}</h5><ul>${g.slice(1).map(i=>`<li>${DATA.D[i]}</li>`).join('')}</ul>`).join('');
  const big=JSON.stringify(ps.map(p=>p[1])).replace(/"/g,'&quot;');
  return `<article class="item rv" style="--c:${color||'var(--line2)'}"><div class="ph${pics[0]!=='c'?' sk':''}" data-big="${big}">${ex?'<span class="ex">Эксклюзивно</span>':''}${ps.map(p=>`<img src="${p[0]}" alt="${name}" loading="lazy">`).join('')}</div><div class="bd"><h4>${name}</h4><div class="kv">${kv}</div>${rest?`<div class="flist more-specs">${rest}</div><button class="toggle">Все особенности</button>`:''}</div></article>`;
}

function pageIndex(){
  const men=['men-1','men-2'][Math.floor(Math.random()*2)],car=['car-1','car-2','car-3'][Math.floor(Math.random()*3)];
  $('#heroArt').innerHTML=`<img class="man" src="${B}/img/main/${men}.png" alt=""><img class="car" src="${B}/img/main/${car}.png" alt="">`;
  online();
}

function pageShop(){
  $('#perkTrack').innerHTML=[...PERKS,...PERKS].map((p,i)=>`<div class="perk"><span class="no">${String(i%15+1).padStart(2,'0')}</span><div><h4>${p[0]}</h4><p>${p[1]}</p></div><span class="v">${p[2]}</span></div>`).join('');
  $('#randoms').innerHTML=RANDOMS.map(r=>`<div class="rpack rv" data-id="${r.id}">${r.timer?`<span class="timer">${r.timer}</span>`:''}<h3>${r.t}</h3><p>${r.d}</p><div class="price">${r.p}<small>₽</small></div><div class="art${r.skin?' sk':''}">${r.skin?r.img.map(s=>`<img src="${B}${s}" alt="">`).join(''):`<img src="${B}${r.img[0]}" alt=""><img class="a" src="${B}${r.img[1]}" alt="">`}</div><div class="acts"><a class="btn btn-ghost btn-sm" href="product.html?id=${r.id}">Посмотреть список</a><button class="btn btn-red btn-sm" data-buy="${r.id}">Купить</button></div></div>`).join('');
  $$('#randoms [data-buy]').forEach(b=>b.onclick=e=>{e.stopPropagation();const r=RANDOMS.find(x=>x.id===b.dataset.buy);pay(r.t,r.p,r.max)});
  $$('#randoms .rpack').forEach(c=>c.onclick=e=>{if(!e.target.closest('a,button')){const r=RANDOMS.find(x=>x.id===c.dataset.id);pay(r.t,r.p,r.max)}});
  const draw=f=>{
    const list=DATA.S.filter(s=>{const p=+s[2];return f==='all'||(f==='a'&&p<3000)||(f==='b'&&p>=3000&&p<7000)||(f==='c'&&p>=7000)});
    $('#sets').innerHTML=list.map(s=>{const sk=s[5]?s[5].split(' '):[];return `<article class="set rv show"><div class="pic"><span class="tag">Игровой набор</span><a class="info" href="product.html?id=${s[0]}" aria-label="Подробнее">${ICO.info}</a>${sk[0]?`<img class="s m" src="${B}/img/shop/skins/${sk[0]}.png" alt="">`:''}${sk[1]?`<img class="s f" src="${B}/img/shop/skins/${sk[1]}.png" alt="">`:''}<img class="c" src="${B}/img/shop/cars/${s[4]}.png" alt="${s[3][0]}" loading="lazy"></div><div class="body"><h3>${s[1]}</h3><ul>${s[3].map(i=>`<li>${i}</li>`).join('')}</ul><div class="buy"><b>${fmt(s[2])} ₽</b><div style="display:flex;gap:6px"><a class="btn btn-ghost btn-sm" href="product.html?id=${s[0]}">Состав</a><button class="btn btn-red btn-sm" data-set="${s[0]}">Купить</button></div></div></div></article>`}).join('');
    $$('#sets [data-set]').forEach(b=>b.onclick=()=>{const s=DATA.S.find(x=>x[0]===b.dataset.set);pay('Игровой набор '+s[1],+s[2],1)});
  };
  $$('#setf .chip').forEach(c=>c.onclick=()=>{$$('#setf .chip').forEach(x=>x.classList.remove('on'));c.classList.add('on');draw(c.dataset.f)});
  draw('all');
  let mi=0;const mg=$('#malGrid');
  mg.innerHTML=MALINA.map((m,i)=>`<button class="mal${i===0?' on':''}" data-i="${i}"><b>${fmt(m[0])}</b><span>малины</span><em>+${fmt(m[1])} бесплатно!</em></button>`).join('');
  const mp=()=>{$('#malPrice').textContent=fmt(MALINA[mi][0])};mp();
  $$('.mal',mg).forEach(b=>b.onclick=()=>{$$('.mal',mg).forEach(x=>x.classList.remove('on'));b.classList.add('on');mi=+b.dataset.i;mp()});
  $('#malBuy').onclick=()=>pay(`Пополнение виртуального счета: ${fmt(MALINA[mi][0])} малины (+${fmt(MALINA[mi][1])} бесплатно)`,MALINA[mi][0],1);
  $('#numBuy').onclick=numbers;
  const tabs=$$('.shop-tabs a');const secs=tabs.map(a=>$(a.getAttribute('href')));
  addEventListener('scroll',()=>{let k=0;secs.forEach((s,i)=>{if(s&&s.getBoundingClientRect().top<200)k=i});tabs.forEach((a,i)=>a.classList.toggle('on',i===k))},{passive:true});
}

function pagePlus(){
  $('#perks').innerHTML=PERKS.map((p,i)=>`<div class="pk rv"><span class="no">${String(i+1).padStart(2,'0')}</span>${p[2]?`<span class="v">${p[2]}</span>`:''}<h4>${p[0]}</h4><p>${p[1]}</p></div>`).join('');
  $('#plans').innerHTML=PLANS.map((p,i)=>`<div class="plan rv${i===0?' best':''}"><h3>${p[0]}<small>Статус M+</small></h3><div class="p">${p[1]}<small> ₽</small></div><button class="btn ${i===0?'btn-white':'btn-red'} btn-block" data-i="${i}">Оформить</button></div>`).join('');
  $$('#plans button').forEach(b=>b.onclick=()=>{const p=PLANS[+b.dataset.i];pay(`Статус M+ на ${p[0]}`,p[1],1)});
}

function pageProduct(){
  const id=new URLSearchParams(location.search).get('id')||'168';
  const P=DATA.P[id];
  if(!P){$('#ptitle').textContent='Товар не найден';return}
  document.title=P.t+' · Малиновка';
  $('#ptitle').textContent=P.t;
  const rnd=RANDOMS.find(r=>r.id===id),set=DATA.S.find(s=>s[0]===id);
  const price=rnd?rnd.p:set?+set[2]:0;
  const intro=[],groups=[];let cur=null;
  P.b.forEach(b=>{if(b.h){cur={h:b.h,r:[]};groups.push(cur)}else if(b.r&&cur)cur.r=b.r;else intro.push(b)});
  const ul=intro.find(b=>b.ul),ps=intro.filter(b=>b.p);
  const bar=rnd?`<div class="rar-bar">${Object.keys(RARP).map(k=>`<i style="width:${RARP[k]}%;background:${RAR[k]}"></i>`).join('')}</div>`:'';
  $('#pintro').innerHTML=`<div class="pbox rv"><p>${ps[0]?ps[0].p:''}</p>${ul?`<ul>${ul.ul.map(l=>`<li>${l}</li>`).join('')}</ul>`:''}${bar}</div><div class="pbox rv">${ps.slice(1).map(p=>`<p>${p.p}</p>`).join('')}${price?`<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:22px"><button class="btn btn-red" id="pbuy">${ICO.cart}Купить за ${fmt(price)} ₽</button><a class="btn btn-ghost" href="shop.html">В магазин</a></div>`:''}</div>`;
  if(price)$('#pbuy').onclick=()=>pay(rnd?rnd.t:'Игровой набор '+set[1],price,rnd?rnd.max:1);
  $('#ptabs').innerHTML=groups.length>1?`<button class="chip on" data-g="all">Все · ${groups.reduce((a,g)=>a+g.r.length,0)}</button>`+groups.map((g,i)=>`<button class="chip" data-g="${i}">${g.h} · ${g.r.length}</button>`).join(''):'';
  const draw=f=>{
    $('#pitems').innerHTML=groups.map((g,i)=>f!=='all'&&+f!==i?'':`<h2 class="grp-title">${RAR[g.h]?`<i style="background:${RAR[g.h]}"></i>`:''}${g.h}${RARP[g.h]?`<span>вероятность ${RARP[g.h]}%</span>`:''}</h2><div class="items">${g.r.map(r=>itemCard(r,RAR[g.h])).join('')}</div>`).join('');
    reveal();
  };
  draw('all');
  $('#ptabs').onclick=e=>{const c=e.target.closest('.chip');if(!c)return;$$('#ptabs .chip').forEach(x=>x.classList.remove('on'));c.classList.add('on');draw(c.dataset.g)};
  $('#pitems').onclick=e=>{const t=e.target.closest('.toggle');if(t){const it=t.closest('.item');it.classList.toggle('open');t.textContent=it.classList.contains('open')?'Скрыть':'Все особенности';return}const ph=e.target.closest('.ph');if(ph){const list=JSON.parse(ph.dataset.big);const k=[...ph.querySelectorAll('img')].indexOf(e.target);lb(list,k<0?0:k)}};
}

function pageRegister(){
  let st=0;const steps=$$('.wstep'),wz=$$('.wiz div');
  const go=i=>{st=i;steps.forEach((s,k)=>s.classList.toggle('on',k===i));wz.forEach((w,k)=>w.classList.toggle('on',k<=i))};
  go(0);
  $('#r1').onsubmit=e=>{e.preventDefault();const v=e.target.l.value.trim();if(v.length<3){toast('Введите логин');return}$('#rlogin').textContent=v;go(1)};
  $('#r2').onsubmit=e=>{e.preventDefault();if(e.target.p.value.length<6){toast('Введите пароль');return}e.target.p.value='';go(2)};
}

function pageLogin(){
  $('#lf').onsubmit=e=>{e.preventDefault();e.target.p.value='';toast('Демоверсия: авторизация работает на официальном сайте malinovka.org')};
}
function pageRestore(){
  $('#rf').onsubmit=e=>{e.preventDefault();toast('Демоверсия: сброс пароля работает на официальном сайте malinovka.org')};
}


function transitions(){
  document.addEventListener('click',e=>{
    const a=e.target.closest('a');
    if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
    if(a.target==='_blank'||a.hasAttribute('download'))return;
    const u=new URL(a.href,location.href);
    if(u.origin!==location.origin||!/\.html$/.test(u.pathname))return;
    if(u.pathname===location.pathname&&u.search===location.search)return;
    e.preventDefault();
    document.body.classList.remove('menu-open');
    document.documentElement.classList.add('leave');
    setTimeout(()=>{location.href=u.href},560);
  });
  addEventListener('pageshow',e=>{if(e.persisted)document.documentElement.classList.remove('leave')});
}

document.addEventListener('DOMContentLoaded',()=>{
  layout();
  transitions();
  const f={index:pageIndex,shop:pageShop,plus:pagePlus,product:pageProduct,register:pageRegister,login:pageLogin,restore:pageRestore}[document.body.dataset.page];
  if(f)f();
  reveal();
  $$('[data-pay-plus]').forEach(b=>b.onclick=()=>pay('Статус M+ на 1 месяц',249,1));
  $$('[data-numbers]').forEach(b=>b.onclick=numbers);
});
